// ---- Circuit (Kit 8) ----
// SG90 servo: signal -> D5, red -> 5V, brown -> GND
// Push button between D4 and GND (INPUT_PULLUP, pressed = LOW)
#define SERVO_PIN 5
#define BTN1 4

#include <Servo.h>
Servo servo;
#define LOCKED_ANGLE 0
#define OPEN_ANGLE 90
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

bool locked = true;

void setup() {
  Serial.begin(9600);
  pinMode(BTN1, INPUT_PULLUP);
  servo.attach(SERVO_PIN);
  servo.write(LOCKED_ANGLE);
  Serial.println("LOCKED");
}

void loop() {
  if (pressed()) {
    locked = !locked;
    servo.write(locked ? LOCKED_ANGLE : OPEN_ANGLE);
    Serial.println(locked ? "LOCKED" : "UNLOCKED");
  }
}

// ---- Circuit (Kit 8) ----
// HX711 board: VCC 5V, GND, DT -> D2, SCK -> D3 (load cell wires E+ E- A- A+ on the left header)
#define HX_DT 2
#define HX_SCK 3

#include <HX711.h>
HX711 scale;
#define CAL_FACTOR 441.5                   // raw counts per gram, found by calibrating with a known weight
void scaleBegin() {
  scale.begin(HX_DT, HX_SCK);
  scale.set_scale(CAL_FACTOR);
  scale.tare();                            // empty platform = 0 g
}
float grams() { return scale.get_units(); }

void setup() {
  Serial.begin(9600);
  scaleBegin();
  Serial.println("Scale tared - put something on the platform");
}

void loop() {
  Serial.print("Weight: ");
  Serial.print(grams(), 1);
  Serial.println(" g");
  delay(500);
}

// ---- Circuit (Kit 8) ----
// INA219: VCC 5V, GND, SDA -> A4, SCL -> A5; the load (D8 -> VIN+ -> VIN- -> 220 ohm -> blue LED -> GND) runs THROUGH the shunt. With the relay (project 43) D8 -> relay COM, relay NO -> VIN+
#define LOAD_PIN 8

#include <Adafruit_INA219.h>
Adafruit_INA219 ina;
float busV, mA, mW;
void readPower() {
  busV = ina.getBusVoltage_V();
  mA = ina.getCurrent_mA();
  mW = busV * mA;
}

void setup() {
  Serial.begin(9600);
  pinMode(LOAD_PIN, OUTPUT);
  digitalWrite(LOAD_PIN, HIGH);            // switch the load on
  if (!ina.begin()) Serial.println("INA219 not found - check SDA / SCL");
}

void loop() {
  readPower();
  Serial.print("Bus "); Serial.print(busV, 2); Serial.print(" V   ");
  Serial.print(mA, 1); Serial.print(" mA   ");
  Serial.print(mW, 1); Serial.println(" mW");
  delay(1000);
}

// ---- Circuit (Kit 8) ----
// MPU6050 (I2C): VCC 5V, GND, SDA -> A4, SCL -> A5, AD0 -> 5V so it answers on 0x69 (the DS3231 owns 0x68)


#include <MPU6050.h>
MPU6050 mpu(0x69);                         // AD0 is tied to 5 V, so the IMU answers on 0x69
int rawX, rawY, rawZ;
float axg, ayg, azg;                       // acceleration in g
void readAccel() {
  mpu.getAcceleration(&rawX, &rawY, &rawZ);
  axg = rawX / 16384.0; ayg = rawY / 16384.0; azg = rawZ / 16384.0;
}
float totalG() { return sqrt(axg * axg + ayg * ayg + azg * azg); }
float tiltDeg() {                          // angle between the board's Z axis and straight up
  float flat = sqrt(axg * axg + ayg * ayg);
  return atan2(flat, azg) * 180.0 / PI;
}
void mpuBegin() { Wire.begin(); mpu.initialize(); }

void setup() {
  Serial.begin(9600);
  mpuBegin();
  if (!mpu.testConnection()) Serial.println("MPU6050 not found - AD0 must be tied to 5 V (address 0x69)");
}

void loop() {
  readAccel();
  int gx, gy, gz;
  mpu.getRotation(&gx, &gy, &gz);
  Serial.print("accel g: "); Serial.print(axg, 2); Serial.print(" "); Serial.print(ayg, 2); Serial.print(" "); Serial.print(azg, 2);
  Serial.print("   gyro deg/s: "); Serial.print(gx / 131); Serial.print(" "); Serial.print(gy / 131); Serial.print(" "); Serial.print(gz / 131);
  Serial.print("   tilt "); Serial.print(tiltDeg(), 0); Serial.println(" deg");
  delay(500);
}

// ---- Circuit (Kit 8) ----
// MAX30102 (I2C 0x57): VIN 5V, GND, SDA -> A4, SCL -> A5


#include <MAX30105.h>
#include <heartRate.h>
MAX30105 pulse;
void pulseBegin() {
  if (!pulse.begin(Wire, I2C_SPEED_FAST)) Serial.println("MAX30102 not found - check the wiring");
  pulse.setup();
  pulse.setPulseAmplitudeRed(0x1F);
  pulse.setPulseAmplitudeGreen(0);
}
long irNow() { return pulse.getIR(); }
long redNow() { return pulse.getRed(); }
bool fingerOn() { return pulse.getIR() > 50000; }

void setup() {
  Serial.begin(115200);
  pulseBegin();
  Serial.println("IR,RED");
}

void loop() {
  Serial.print(irNow());
  Serial.print(",");
  Serial.println(redNow());
  delay(50);
}

