  if (checkForBeat(ir)) {
    long delta = millis() - lastBeat;
    bool firstBeat = (lastBeat == 0);        // the first beat has no previous beat to measure from
    lastBeat = millis();
    float b = 60000.0 / delta;
    if (!firstBeat && b > 40 && b < 200) {
      rates[rateIdx] = b;
      rateIdx = (rateIdx + 1) % 4;
      float sum = 0; int n = 0;
