#define FREEFALL_G 0.4
#define IMPACT_G 2.0
bool freefall = false;
unsigned long freefallAt = 0;

void setup() {
  Serial.begin(9600);
  pinMode(BUZZER, OUTPUT); pinMode(RED_LED, OUTPUT); pinMode(GREEN_LED, OUTPUT);
  mpuBegin();
  digitalWrite(GREEN_LED, HIGH);           // green = monitoring
  Serial.println("fall detector armed");
}

void loop() {
  readAccel();
  float g = totalG();
  if (g < FREEFALL_G && !freefall) { freefall = true; freefallAt = millis(); }
  if (freefall && g > IMPACT_G && millis() - freefallAt < 500) {
    Serial.println("FALL DETECTED");
    digitalWrite(GREEN_LED, LOW); digitalWrite(RED_LED, HIGH); digitalWrite(BUZZER, HIGH);
    delay(3000);
    digitalWrite(RED_LED, LOW); digitalWrite(BUZZER, LOW); digitalWrite(GREEN_LED, HIGH);
    freefall = false;
  }
  if (freefall && millis() - freefallAt > 500) freefall = false;     // no impact followed: it was just a drop of the hand
  delay(5);
}

