String U0 = "DE AD BE EF";
String U1 = "01 02 03 04";
String U2 = "AA BB CC DD";
#define NUSERS 3
// EEPROM: byte 0 = day of the month; user u uses 8 bytes at 1 + 8u:
//   +0 state (1 = in)   +1,+2 seconds present (low, high)   +3..+6 time of the last IN (unix time)   +7 visits

int slotOf(String uid) {
  if (uid == U0) return 0;
  if (uid == U1) return 1;
  if (uid == U2) return 2;
  return -1;
}
int base(int u) { return 1 + 8 * u; }
long readLong(int a) { return ((long)EEPROM.read(a) << 24) | ((long)EEPROM.read(a + 1) << 16) | ((long)EEPROM.read(a + 2) << 8) | EEPROM.read(a + 3); }
void writeLong(int a, long v) { EEPROM.write(a, (v >> 24) & 255); EEPROM.write(a + 1, (v >> 16) & 255); EEPROM.write(a + 2, (v >> 8) & 255); EEPROM.write(a + 3, v & 255); }
int secondsPresent(int u) { return EEPROM.read(base(u) + 1) + 256 * EEPROM.read(base(u) + 2); }

void newDay(int day) {
  for (int i = 1; i < 1 + 8 * NUSERS; i++) EEPROM.write(i, 0);
  EEPROM.write(0, day);
}
void report() {
  Serial.println("---- daily report ----");
  for (int u = 0; u < NUSERS; u++) {
    Serial.print("user "); Serial.print(u + 1);
    Serial.print("  visits "); Serial.print(EEPROM.read(base(u) + 7));
    Serial.print("  present "); Serial.print(secondsPresent(u)); Serial.print(" s");
    Serial.println(EEPROM.read(base(u)) == 1 ? "  (still IN)" : "  (out)");
  }
}

