  Serial.begin(9600);
  pinMode(BTN1, INPUT_PULLUP);
  rtc.begin();
  lcdBegin();
  rfidBegin();
  if (EEPROM.read(0) != rtc.now().day()) newDay(rtc.now().day());
  lcdRow(0, "Attendance");
  lcdRow(1, "swipe IN / OUT");
}

