  if (pressed()) report();
  if (!readCard()) return;
  int u = slotOf(cardUid);
  if (u < 0) { lcdRow(0, "Unknown card"); lcdRow(1, cardUid); return; }
  long now = rtc.now().unixtime();
  int a = base(u);
  if (EEPROM.read(a) == 0) {                                   // IN
    EEPROM.write(a, 1);
    writeLong(a + 3, now);
    EEPROM.write(a + 7, EEPROM.read(a + 7) + 1);
    lcdRow(0, "User " + String(u + 1) + " IN");
    lcdRow(1, clockText(rtc.now()));
  } else {                                                     // OUT: add the time spent inside
    int total = secondsPresent(u) + (now - readLong(a + 3));
    EEPROM.write(a, 0);
    EEPROM.write(a + 1, total & 255);
    EEPROM.write(a + 2, (total >> 8) & 255);
    lcdRow(0, "User " + String(u + 1) + " OUT");
    lcdRow(1, "total " + String(total) + " s");
  }
}

