  scaleBegin();
  rfidBegin();
  nextDose = rtc.now().unixtime() + FIRST_DOSE_S;
}

void loop() {
  DateTime now = rtc.now();
  bool card = readCard();
  if (state == 0) {
    if (now.unixtime() >= nextDose) { state = 1; Serial.println(clockText(now) + "  DOSE DUE"); }
    lcdRow(0, "Time " + clockText(now));
    lcdRow(1, "next dose " + String((long)(nextDose - now.unixtime())) + "s");
  } else if (state == 1) {
    digitalWrite(BUZZER, (millis() / 400) % 3 == 0 ? HIGH : LOW);
    lcdRow(0, "TAKE MEDICINE");
    lcdRow(1, "swipe card");
    if (card && cardUid == CARER) {
      digitalWrite(BUZZER, LOW);
      before = grams();
      servo.write(OPEN_ANGLE);
      state = 2;
      Serial.println(clockText(now) + "  lid open, weight " + String(before, 0) + " g");
    }
  } else {
    lcdRow(0, "Lid open " + String(grams(), 0) + "g");
    lcdRow(1, "take pills,swipe");
    if (card && cardUid == CARER) {
      servo.write(LOCKED_ANGLE);
      float taken = before - grams();
      if (taken >= DOSE_MIN_G && taken <= DOSE_MAX_G) {
        doses++;
        lcdRow(0, "Dose OK " + String(taken, 0) + " g");
        lcdRow(1, "doses today " + String(doses));
        Serial.println(clockText(now) + "  dose taken, " + String(taken, 0) + " g");
        nextDose = now.unixtime() + DOSE_EVERY_S;
        state = 0;
        beep(200);
      } else {
        lcdRow(0, taken < DOSE_MIN_G ? "Too little!" : "Too much!");
        lcdRow(1, "check the box");
        Serial.println(clockText(now) + "  WRONG DOSE " + String(taken, 0) + " g");
        beeps(3);
        nextDose = now.unixtime() + 20;                 // remind again soon
        state = 0;
      }
      delay(1500);
    }
  }
  delay(50);
}

