#define TRIP_G 800.0
#define KNOWN_G 200.0
int mode = 0;                              // 0 weigh, 1 count, 2 calibrate, 3 report
int items = 0;
float batchTotal = 0;
bool tripped = false;
float factor = CAL_FACTOR;

void setup() {
  Serial.begin(9600);
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(BUZZER, OUTPUT);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  lcdBegin();
  scaleBegin();
}

void calibrate() {
  scale.set_scale(1);                                          // raw counts above the tare offset
  float counts = scale.get_units();
  if (counts > 1000) { factor = counts / KNOWN_G; Serial.print("new factor "); Serial.println(factor, 2); }
  scale.set_scale(factor);
}

void loop() {
  float w = grams();
  if (w > TRIP_G && !tripped) { tripped = true; digitalWrite(RELAY_PIN, RELAY_ON); Serial.println("OVERLOAD - relay tripped"); }
  if (tripped && w < TRIP_G - 50) { tripped = false; digitalWrite(RELAY_PIN, RELAY_OFF); }
  digitalWrite(BUZZER, tripped ? HIGH : LOW);

  int e = btnEvent();
  if (e == 1) mode = (mode + 1) % 4;
  if (e == 2) {
    if (mode == 0) scale.tare();
    if (mode == 1 && w > 1) { items++; batchTotal += w; Serial.print("item "); Serial.print(items); Serial.print(": "); Serial.print(w, 1); Serial.println(" g"); }
    if (mode == 2) calibrate();
    if (mode == 3) { Serial.print("REPORT: "); Serial.print(items); Serial.print(" items, total "); Serial.print(batchTotal, 1); Serial.println(" g"); items = 0; batchTotal = 0; }
  }
  if (tripped) { lcdRow(0, "OVERLOAD TRIP"); lcdRow(1, String(w, 0) + " g"); }
  else if (mode == 0) { lcdRow(0, "WEIGH (hold=tare)"); lcdRow(1, String(w, 1) + " g"); }
  else if (mode == 1) { lcdRow(0, "COUNT " + String(items) + " items"); lcdRow(1, String(w, 1) + "g T" + String(batchTotal, 0)); }
  else if (mode == 2) { lcdRow(0, "CAL put " + String(KNOWN_G, 0) + " g"); lcdRow(1, "factor " + String(factor, 1)); }
  else { lcdRow(0, "REPORT hold=print"); lcdRow(1, String(items) + " items " + String(batchTotal, 0) + "g"); }
  delay(30);
}

