#define N 40
#define ALARM_MG 200
float samp[N];
unsigned long lastLog = 0;
String lastAlarm = "none";

void setup() {
  Serial.begin(9600);
  pinMode(BUZZER, OUTPUT);
  mpuBegin();
  rtc.begin();
  lcdBegin();
  Serial.println("time,rms_mg");
}

void loop() {
  float mean = 0;
  for (int i = 0; i < N; i++) {                                // about 0.4 s of samples
    readAccel();
    samp[i] = totalG();
    mean += samp[i];
    delay(10);
  }
  mean /= N;
  float sq = 0;
  for (int i = 0; i < N; i++) sq += (samp[i] - mean) * (samp[i] - mean);
  float rmsMg = sqrt(sq / N) * 1000.0;
  bool alarm = (rmsMg > ALARM_MG);
  digitalWrite(BUZZER, alarm ? HIGH : LOW);
  if (alarm && millis() - lastLog > 2000) {
    lastLog = millis();
    lastAlarm = clockText(rtc.now());
    Serial.print(lastAlarm); Serial.print(","); Serial.println(rmsMg, 0);
  }
  lcdRow(0, "RMS " + String(rmsMg, 0) + " mg " + (alarm ? "!!" : "ok"));
  lcdRow(1, "last " + lastAlarm);
}

