#define LIMIT_S 20                         // maximum continuous use
bool on = false;
unsigned long onSince = 0, lastMs = 0;
float sessionMwh = 0;
String onStamp = "";

void switchOn() {
  on = true; onSince = millis(); lastMs = millis(); sessionMwh = 0;
  digitalWrite(RELAY_PIN, RELAY_ON);
  onStamp = clockText(rtc.now());
  Serial.println("ON  " + onStamp);
}
void switchOff(String why) {
  on = false;
  digitalWrite(RELAY_PIN, RELAY_OFF);
  Serial.print("OFF " + clockText(rtc.now()) + "  used "); Serial.print((millis() - onSince) / 1000); Serial.print(" s, ");
  Serial.print(sessionMwh, 4); Serial.println(" mWh  (" + why + ")");
}

void setup() {
  Serial.begin(9600);
  pinMode(BTN1, INPUT_PULLUP);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  pinMode(LOAD_PIN, OUTPUT); digitalWrite(LOAD_PIN, HIGH);
  ina.begin();
  rtc.begin();
  lcdBegin();
}

void loop() {
  readPower();
  if (pressed()) { if (on) switchOff("button"); else switchOn(); }
  if (on) {
    unsigned long ms = millis();
    sessionMwh += mW * (ms - lastMs) / 3600000.0;
    lastMs = ms;
    if (ms - onSince > LIMIT_S * 1000UL) switchOff("time limit");
  }
  if (on) {
    lcdRow(0, "ON " + String((millis() - onSince) / 1000) + "s " + String(mA, 1) + "mA");
    lcdRow(1, String(sessionMwh, 4) + " mWh");
  } else {
    lcdRow(0, "OFF  " + String(mA, 1) + " mA");
    lcdRow(1, "press to start");
  }
  delay(30);
}

