#define PEAK_G 1.3
int page = 0;
int bpm = 0, steps = 0;
long lastBeat = 0;
bool above = false;
unsigned long lastStep = 0, lastDraw = 0;

void title(String s) { oled.setTextSize(1); oled.setCursor(0, 0); oled.print(s); }

void draw() {
  oled.clearDisplay();
  if (page == 0) {
    DateTime now = rtc.now();
    title("TIME");
    oled.setTextSize(2); oled.setCursor(0, 20); oled.print(clockText(now));
    oled.setTextSize(1); oled.setCursor(0, 48); oled.print(dateText(now));
  } else if (page == 1) {
    title("HEART RATE");
    oled.setTextSize(3); oled.setCursor(0, 22); oled.print(bpm);
    oled.setTextSize(1); oled.setCursor(80, 40); oled.print("bpm");
  } else if (page == 2) {
    title("STEPS");
    oled.setTextSize(3); oled.setCursor(0, 22); oled.print(steps);
  } else {
    title("BATTERY");
    int pct = constrain(map((int)(busV * 100), 400, 490, 0, 100), 0, 100);
    oled.setTextSize(2); oled.setCursor(0, 16); oled.print(busV, 2); oled.print(" V");
    oled.drawRect(0, 40, 100, 14, SSD1306_WHITE);
    oled.fillRect(2, 42, pct, 10, SSD1306_WHITE);
    oled.setTextSize(1); oled.setCursor(0, 56); oled.print(pct); oled.print("%  "); oled.print(mA, 1); oled.print(" mA");
  }
  oled.display();
}

void setup() {
  Serial.begin(9600);
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(LOAD_PIN, OUTPUT); digitalWrite(LOAD_PIN, HIGH);
  rtc.begin();
  mpuBegin();
  ina.begin();
  oledBegin();
  pulseBegin();
}

void loop() {
  if (pressed()) { page = (page + 1) % 4; Serial.print("page "); Serial.println(page); }
  readAccel();                                                  // steps: rising edge through 1.3 g
  float g = totalG();
  if (g > PEAK_G && !above && millis() - lastStep > 250) { steps++; lastStep = millis(); }
  above = (g > PEAK_G);
  long ir = irNow();                                            // heart rate
  if (ir < 50000) bpm = 0;
  else if (checkForBeat(ir)) {
    long delta = millis() - lastBeat;
    bool firstBeat = (lastBeat == 0);        // the first beat has no previous beat to measure from
    lastBeat = millis();
    float b = 60000.0 / delta;
    if (!firstBeat && b > 40 && b < 200) bpm = (int)b;
  }
  if (millis() - lastDraw > 250) { lastDraw = millis(); readPower(); draw(); }
  delay(10);
}

