#define IMPACT_G 2.0
#define LYING_DEG 60.0
#define CANCEL_MS 8000
int state = 0;                             // 0 monitoring, 1 checking orientation, 2 pre-alarm, 3 ALARM
unsigned long since = 0;

void setup() {
  Serial.begin(9600);
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(BUZZER, OUTPUT); pinMode(RED_LED, OUTPUT); pinMode(GREEN_LED, OUTPUT);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  mpuBegin();
  digitalWrite(GREEN_LED, HIGH);
  Serial.println("monitoring");
}

void allOff() {
  digitalWrite(BUZZER, LOW); digitalWrite(RED_LED, LOW); digitalWrite(RELAY_PIN, RELAY_OFF); digitalWrite(GREEN_LED, HIGH);
}

void loop() {
  readAccel();
  bool btn = pressed();
  if (state == 0) {
    if (totalG() > IMPACT_G) { state = 1; since = millis(); Serial.println("impact!"); }
  } else if (state == 1) {
    if (millis() - since > 1500) {                              // wait for the movement to settle, then look at the orientation
      if (tiltDeg() > LYING_DEG) { state = 2; since = millis(); digitalWrite(GREEN_LED, LOW); Serial.println("lying down: pre-alarm, press the button to cancel"); }
      else { state = 0; Serial.println("up again: false alarm"); }
    }
  } else if (state == 2) {
    digitalWrite(BUZZER, (millis() / 500) % 2 == 0 ? HIGH : LOW);
    digitalWrite(RED_LED, (millis() / 500) % 2 == 0 ? HIGH : LOW);
    if (btn) { state = 0; allOff(); Serial.println("cancelled"); }
    else if (millis() - since > CANCEL_MS) { state = 3; Serial.println("ALERT sent"); }
  } else {
    digitalWrite(BUZZER, HIGH); digitalWrite(RED_LED, HIGH); digitalWrite(RELAY_PIN, RELAY_ON);
    if (btn) { state = 0; allOff(); Serial.println("alert cleared"); }
  }
  delay(10);
}

