String OWNER = "DE AD BE EF";
String PIN = "SLS";                        // S = short press, L = long press (hold 1 s)
#define PIN_TIMEOUT_MS 10000
bool waitingPin = false;
String entered = "";
unsigned long pinStart = 0;

void logLine(String what) {
  Serial.println(clockText(rtc.now()) + "  " + cardUid + "  " + what);
}
void deny(String why) {
  waitingPin = false;
  lcdRow(0, "ACCESS DENIED");
  lcdRow(1, why);
  logLine("DENIED " + why);
  beeps(3);
  delay(1000);
}

void setup() {
  Serial.begin(9600);
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(BUZZER, OUTPUT);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  servo.attach(SERVO_PIN);
  servo.write(LOCKED_ANGLE);
  rtc.begin();
  lcdBegin();
  rfidBegin();
}

void loop() {
  if (!waitingPin) {
    lcdRow(0, "Door locked");
    lcdRow(1, "1) show card");
    if (readCard()) {
      if (cardUid == OWNER) { waitingPin = true; entered = ""; pinStart = millis(); beep(60); }
      else deny("unknown card");
    }
  } else {
    lcdRow(0, "2) enter PIN");
    lcdRow(1, "presses: " + String(entered.length()) + "/" + String(PIN.length()));
    int e = btnEvent();
    if (e == 1) { entered += "S"; beep(30); }
    if (e == 2) { entered += "L"; beep(30); }
    if (entered.length() >= PIN.length()) {
      if (entered == PIN) {
        waitingPin = false;
        lcdRow(0, "WELCOME");
        lcdRow(1, clockText(rtc.now()));
        logLine("OPEN");
        servo.write(OPEN_ANGLE);
        digitalWrite(RELAY_PIN, RELAY_ON);
        beep(200);
        delay(3000);
        servo.write(LOCKED_ANGLE);
        digitalWrite(RELAY_PIN, RELAY_OFF);
      } else deny("wrong PIN");
    } else if (millis() - pinStart > PIN_TIMEOUT_MS) deny("PIN timeout");
  }
  delay(20);
}

