int btnEvent() {                           // 0 = nothing, 1 = short press, 2 = long press (held for 0.8 s)
  if (digitalRead(BTN1) == HIGH) return 0;
  unsigned long t0 = millis();
  while (digitalRead(BTN1) == LOW) {
    delay(5);
    if (millis() - t0 > 800) { while (digitalRead(BTN1) == LOW) delay(5); return 2; }
  }
  return 1;
}

float anticipate = 3.0;                    // grams still falling when the gate closes - adjusted after every run
int ti = 1;
bool running = false;
float target = 50;
unsigned long startMs = 0;
String result = "";

float targetFor(int i) { if (i == 0) return 25; if (i == 1) return 50; if (i == 2) return 100; return 200; }

void finish(String msg) {
  servo.write(LOCKED_ANGLE);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  running = false;
  delay(1500);                                                  // let the falling material settle
  float final = grams();
  result = msg + " " + String(final, 1) + "g";
  if (msg == "Done") {
    anticipate = constrain(anticipate + (final - target) * 0.5, 0, 20);   // overshoot -> stop earlier next time
    Serial.print("dispensed "); Serial.print(final, 1); Serial.print(" g, anticipation now "); Serial.println(anticipate, 1);
  } else Serial.println(msg);
}

void setup() {
  Serial.begin(9600);
  pinMode(BTN1, INPUT_PULLUP);
  digitalWrite(RELAY_PIN, RELAY_OFF);
  pinMode(RELAY_PIN, OUTPUT);
  servo.attach(SERVO_PIN);
  servo.write(LOCKED_ANGLE);
  lcdBegin();
  scaleBegin();
  target = targetFor(ti);
}

void loop() {
  float w = grams();
  if (!running) {
    int e = btnEvent();
    if (e == 1) { ti = (ti + 1) % 4; target = targetFor(ti); result = ""; }
    if (e == 2) {
      scale.tare();                                             // zero with the empty container in place
      servo.write(OPEN_ANGLE);
      digitalWrite(RELAY_PIN, RELAY_ON);
      running = true;
      startMs = millis();
      Serial.print("dispensing "); Serial.print(target, 0); Serial.println(" g");
    }
    lcdRow(0, "Target " + String(target, 0) + " g");
    lcdRow(1, result.length() > 0 ? result : "hold to start");
  } else {
    lcdRow(0, "Dispensing...");
    lcdRow(1, String(w, 1) + " / " + String(target, 0) + " g");
    if (w >= target - anticipate) finish("Done");
    else if (millis() - startMs > 30000) finish("No flow!");
  }
  delay(50);
}

