int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

#define N 20
#define POST 10                            // samples recorded after the trigger
#define IMPACT_DEV 0.6
int bufG[N];                               // acceleration deviation from 1 g, in milli-g
int bufI[N];                               // current in 0.1 mA
int bufH[N];                               // heart rate
int head = 0, filled = 0;
int state = 0;                             // 0 recording, 1 post-trigger, 2 frozen
int postLeft = 0;
String why = "";
String stamp = "";
int bpm = 0;
long lastBeat = 0;
unsigned long lastSample = 0;

void trigger(String reason) {
  if (state != 0) return;
  state = 1; postLeft = POST; why = reason;
  stamp = dateText(rtc.now()) + " " + clockText(rtc.now());
}
void dump() {
  Serial.println("==== BLACK BOX " + stamp + " trigger: " + why + " ====");
  Serial.println("t(s),dev_mg,mA x10,bpm");
  int start = (head - N + N) % N;                               // oldest sample
  for (int i = 0; i < N; i++) {
    int k = (start + i) % N;
    Serial.print((i - (N - POST)) * 0.2, 1); Serial.print(",");
    Serial.print(bufG[k]); Serial.print(","); Serial.print(bufI[k]); Serial.print(","); Serial.println(bufH[k]);
  }
}

void setup() {
  Serial.begin(9600);
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(LOAD_PIN, OUTPUT); digitalWrite(LOAD_PIN, HIGH);
  mpuBegin();
  ina.begin();
  pulseBegin();
  rtc.begin();
  lcdBegin();
}

void loop() {
  long ir = irNow();                                            // keep the beat detector running at full speed
  if (ir < 50000) bpm = 0;
  else if (checkForBeat(ir)) {
    long delta = millis() - lastBeat;
    bool firstBeat = (lastBeat == 0);        // the first beat has no previous beat to measure from
    lastBeat = millis();
    float b = 60000.0 / delta;
    if (!firstBeat && b > 40 && b < 200) bpm = (int)b;
  }
  readAccel();
  float dev = abs(totalG() - 1.0);
  bool btn = pressed();
  if (state == 0 && dev > IMPACT_DEV) trigger("IMPACT");
  if (state == 0 && btn) trigger("BUTTON");
  else if (state == 2 && btn) { state = 0; filled = 0; head = 0; }       // re-arm
  if (state != 2 && millis() - lastSample >= 200) {
    lastSample = millis();
    readPower();
    bufG[head] = (int)(dev * 1000); bufI[head] = (int)(mA * 10); bufH[head] = bpm;
    head = (head + 1) % N;
    if (filled < N) filled++;
    if (state == 1) {
      postLeft--;
      if (postLeft <= 0) { state = 2; dump(); }
    }
  }
  lcdRow(0, state == 0 ? "REC " + String(filled) + "/" + String(N) : state == 1 ? "TRIGGER " + why : "FROZEN " + why);
  lcdRow(1, state == 2 ? "button = re-arm" : String(dev * 1000, 0) + "mg " + String(mA, 0) + "mA " + String(bpm));
  delay(10);
}

// ---- Circuit (Kit 8) ----
// MFRC522: 3.3V (never 5 V!), GND, SDA(SS) -> D10, RST -> D9, SCK -> D13, MOSI -> D11, MISO -> D12
// DS3231 RTC (I2C 0x68): VCC 5V, GND, SDA -> A4, SCL -> A5
// HX711 board: VCC 5V, GND, DT -> D2, SCK -> D3 (load cell wires E+ E- A- A+ on the left header)
// SG90 servo: signal -> D5, red -> 5V, brown -> GND
// Relay module: DC+ 5V, DC- GND, IN <- D6 (active LOW)
// MPU6050 (I2C): VCC 5V, GND, SDA -> A4, SCL -> A5, AD0 -> 5V so it answers on 0x69 (the DS3231 owns 0x68)
// INA219: VCC 5V, GND, SDA -> A4, SCL -> A5; the load (D8 -> VIN+ -> VIN- -> 220 ohm -> blue LED -> GND) runs THROUGH the shunt. With the relay (project 43) D8 -> relay COM, relay NO -> VIN+
// SSD1306 OLED (I2C 0x3C): VCC 5V, GND, SDA -> A4, SCL -> A5
// 16x2 LCD (I2C 0x27): VCC 5V, GND, SDA -> A4, SCL -> A5
// Active buzzer: + -> D7, - -> GND
// Green LED anode -> 220 ohm -> A1, cathode -> GND
// Red LED anode -> 220 ohm -> A0, cathode -> GND
#define RFID_SS 10
#define RFID_RST 9
#define HX_DT 2
#define HX_SCK 3
#define SERVO_PIN 5
#define RELAY_PIN 6
#define RELAY_ON LOW
#define RELAY_OFF HIGH
#define LOAD_PIN 8
#define BUZZER 7
#define GREEN_LED A1
#define RED_LED A0

#include <SPI.h>
#include <MFRC522.h>
MFRC522 rfid(RFID_SS, RFID_RST);
String hex2(int v) {                        // two hex digits
  String h = "0123456789ABCDEF";
  return String(h.charAt((v >> 4) & 15)) + String(h.charAt(v & 15));
}

String cardUid = "";                       // UID of the last card read, e.g. "DE AD BE EF"
int uidB[10];                              // the same UID as raw bytes
bool readCard() {                          // true when a new card has been read into cardUid
  if (!rfid.PICC_IsNewCardPresent()) return false;
  if (!rfid.PICC_ReadCardSerial()) return false;
  cardUid = "";
  for (int i = 0; i < rfid.uid.size; i++) {
    if (i > 0) cardUid += " ";
    cardUid += hex2(rfid.uid.uidByte[i]);
    uidB[i] = rfid.uid.uidByte[i];
  }
  rfid.PICC_HaltA();
  return true;
}
void rfidBegin() { SPI.begin(); rfid.PCD_Init(); }
#include <RTClib.h>
RTC_DS3231 rtc;
String two(int v) { if (v < 10) return "0" + String(v); return String(v); }
String clockText(DateTime t) { return two(t.hour()) + ":" + two(t.minute()) + ":" + two(t.second()); }
String dateText(DateTime t) { return String(t.year()) + "-" + two(t.month()) + "-" + two(t.day()); }
#include <Servo.h>
Servo servo;
#define LOCKED_ANGLE 0
#define OPEN_ANGLE 90
#include <HX711.h>
HX711 scale;
#define CAL_FACTOR 441.5                   // raw counts per gram, found by calibrating with a known weight
void scaleBegin() {
  scale.begin(HX_DT, HX_SCK);
  scale.set_scale(CAL_FACTOR);
  scale.tare();                            // empty platform = 0 g
}
float grams() { return scale.get_units(); }
#include <MPU6050.h>
MPU6050 mpu(0x69);                         // AD0 is tied to 5 V, so the IMU answers on 0x69
int rawX, rawY, rawZ;
float axg, ayg, azg;                       // acceleration in g
void readAccel() {
  mpu.getAcceleration(&rawX, &rawY, &rawZ);
  axg = rawX / 16384.0; ayg = rawY / 16384.0; azg = rawZ / 16384.0;
}
float totalG() { return sqrt(axg * axg + ayg * ayg + azg * azg); }
float tiltDeg() {                          // angle between the board's Z axis and straight up
  float flat = sqrt(axg * axg + ayg * ayg);
  return atan2(flat, azg) * 180.0 / PI;
}
void mpuBegin() { Wire.begin(); mpu.initialize(); }
#include <Adafruit_INA219.h>
Adafruit_INA219 ina;
float busV, mA, mW;
void readPower() {
  busV = ina.getBusVoltage_V();
  mA = ina.getCurrent_mA();
  mW = busV * mA;
}
